type Fields={categoryId:string;plantDiet:PlantDiet;description:string;declarations:Declarations;allergens:Allergens;name:string;market:string;category:string;specialty:string;price:string;halal:'declared'|'non-halal'|'not-declared';lot:string;opens:string;closes:string;latitude:string;longitude:string;open:boolean;ingredients:string;food:string;prepared:string;quantity:string;storage:'ambient'|'chilled'|'hot-held'|'unknown';note:string}
const defaults:Fields={categoryId:'',plantDiet:{...unknownPlant},description:'',declarations:{...unknownDeclarations},allergens:{...unknownAllergens,contains:[]},name:'',market:'',category:'Prepared food',specialty:'',price:'5.00',halal:'not-declared',lot:'',opens:'17:00',closes:'22:00',latitude:'',longitude:'',open:true,ingredients:'',food:'',prepared:'',quantity:'',storage:'unknown',note:''}
function localTime(date:Date) {return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
export function VendorPage({mode,view}:{mode:AppMode;view:'dashboard'|'stall'|'batches'}) {return mode==='fixture'?<Workspace mode={mode} view={view}/>:<RoleGate required="vendor"><Workspace mode={mode} view={view}/></RoleGate>}
function Workspace({mode,view}:{mode:AppMode;view:'dashboard'|'stall'|'batches'}) {
  const {actor}=useAuth();const cache=useQueryClient();
  const now=useNow(mode==='fixture'?fixtureGateway:connectedGateway)
  const fresh=useQuery({queryKey:['freshness',mode],queryFn:()=>freshness(mode),enabled:view==='dashboard',refetchInterval:10000,refetchIntervalInBackground:false,retry:1});const query=useQuery({queryKey:['vendor',mode,actor?.id],queryFn:()=>workspace(mode)})
  const discovery=useQuery({queryKey:['discovery',mode],queryFn:()=> (mode==='fixture'?fixtureGateway:connectedGateway).getDiscovery()})
  const [selected,setSelected]=useState('');const [editFood,setEditFood]=useState('');const [form,setForm]=useState<'stall'|'food'|'batch'|null>(null)
  useEffect(()=>{if(form){const frame=requestAnimationFrame(()=>document.getElementById('vendor-listing-form')?.scrollIntoView({block:'start'}));return()=>cancelAnimationFrame(frame)}},[form])
  const [actionRetry,setActionRetry]=useState<{command:Command;request:string}|null>(null)
  const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [sources,setSources]=useState<string[]>([])
  const s=query.data;const stall=s?.stalls.find(x=>x.id===selected)??s?.stalls[0]
  async function act(command:Command,request:string=crypto.randomUUID()) {setBusy(true);setMessage('');setActionRetry({command,request});try {await save(mode,command,request);setActionRetry(null);await Promise.all([cache.invalidateQueries({queryKey:['vendor',mode]}),cache.invalidateQueries({queryKey:['discovery',mode]})]);setSources([]);setMessage(mode==='fixture'?'Saved in the demo on this device.':'Saved to your account.')}catch(e){if(e instanceof SaveError&&e.definite)setActionRetry(null);setMessage(errorText(e,'Save failed'))}finally{setBusy(false)}}
  if(query.isPending)return <p className="panel" role="status">{' '+ui("Loading your stall workspace…")+' '}</p>
  if(!s)return <div className="panel"><h1>{' '+ui("Workspace unavailable")+' '}</h1><p>{String(query.error?.message)}</p><button className="button secondary" onClick={()=>void query.refetch()}>{' '+ui("Retry")+' '}</button></div>
  const foods=s.foods.filter(f=>f.stall_id===stall?.id);const batches=s.batches.filter(b=>foods.some(f=>f.id===b.food_item_id)).sort((a,b)=>Date.parse(b.uploaded_at)-Date.parse(a.uploaded_at))
  return <>{view!=='dashboard'&&<header className="page-intro"><div className="eyebrow">{' '+ui("HAWKER WORKSPACE")+' '}{mode==='fixture'?ui("· FICTIONAL DEMO"):''}</div><h1>{view==='stall'?ui("Stall & menu"):ui("Batch history")}</h1><p>{' '+ui("Every preparation gets its own batch number and original photo. New batches await a handling policy; no safety claim or clearance offer is inferred.")+' '}</p><NavLink className="button primary" to="/hawker/voice">{' '+ui("Voice & quick entry")+' '}</NavLink><NavLink className="back-link" to="/profile">{ui('Language & privacy')}</NavLink></header>}{view==='dashboard'&&stall&&<HawkerDashboard workspace={fresh.data?{...fresh.data.workspace,freshness:fresh.data.state}:s} stall={stall} foods={foods} batches={(fresh.data?.workspace.batches??batches).filter(b=>foods.some(f=>f.id===b.food_item_id)).sort((a,b)=>Date.parse(b.prepared_at)-Date.parse(a.prepared_at))} now={now} onFood={()=>{setEditFood('');setForm('food')}} onBatch={()=>setForm('batch')} onStall={id=>{setSelected(id);setForm(null)}}/>}{view!=='dashboard'&&<AdvisorySummary workspace={s}/>}{message&&<p className="panel" role="status">{ui(message)}</p>}{actionRetry&&<div className="panel"><p>{' '+ui("Action result is uncertain. Retry the same action before making another change.")+' '}</p><button className="button primary" disabled={busy} onClick={()=>void act(actionRetry.command,actionRetry.request)}>{' '+ui("Retry action")+' '}</button></div>}<div className="vendor-toolbar workspace-management"><label>{' '+ui("Choose stall")+' '}<select value={stall?.id??''} onChange={e=>{setSelected(e.target.value);setForm(null)}}>{s.stalls.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><button className="button secondary" onClick={()=>{setSelected('new');setForm('stall')}}><Plus size={17}/>{' '+ui("New stall")+' '}</button>{stall&&<><button className="button secondary" disabled={busy||!!actionRetry} onClick={()=>void act({kind:'stall',data:{...stall,confirm_availability:true}})}>{ui('Confirm current availability')}</button><Availability at={stall.availability_confirmed_at} now={now}/><button className="button secondary" onClick={()=>setForm('stall')}>{' '+ui("Edit stall")+' '}</button><button className="button secondary" onClick={()=>{setEditFood('');setForm('food')}}>{' '+ui("Add food")+' '}</button><button className="button primary" onClick={()=>setForm('batch')}>{' '+ui("New batch prepared")+' '}</button></>}</div>
    {form&&<div id="vendor-listing-form"><ListingForm key={`${form}:${selected}:${editFood}`} foodId={editFood} mode={mode} kind={form} data={s} stallId={selected==='new'?'':stall?.id??''} markets={discovery.data?.markets.map(m=>({id:m.id,name:m.name,latitude:m.latitude,longitude:m.longitude}))??[]} onSaved={async()=>{setForm(null);await cache.invalidateQueries({queryKey:['vendor',mode]});await cache.invalidateQueries({queryKey:['discovery',mode]})}} onClose={()=>setForm(null)}/></div>}
    {stall&&view!=='dashboard'&&<section className="panel detail-panel"><div className="eyebrow">{stall.lot?'LOT '+stall.lot:''}</div><h2><Store size={21}/> {stall.name}</h2><p>{stall.description}</p><BusinessStatements value={stall.declarations} at={stall.declarations_recorded_at}/><p>{stall.specialty} · {stall.open?ui("Vendor open"):ui("Vendor closed")} · {stall.opens}–{stall.closes}</p><p>{stall.halal==='declared'?ui("Hawker-declared halal, not certified"):stall.halal==='non-halal'?ui("Non-halal"):ui("Halal status not declared")}</p><DemoImage image={stall.name.toLowerCase().includes('bara senja')?'satayStall':stall.name.toLowerCase().includes('dapur embun')?'riceStall':undefined} description={`${stall.name} stall frontage and menu board`}/><NavLink className="back-link" to={`/stalls/${stall.id}`}>{' '+ui("View customer listing")+' '}</NavLink></section>}
    {view==='stall'&&<section className="panel detail-panel"><h2>{' '+ui("Menu")+' '}</h2>{foods.map(f=><article className="menu-item" key={f.id}><h3>{f.name} {' '+ui("· RM")+' '}{(f.price_sen/100).toFixed(2)}</h3><button className="button secondary" onClick={()=>{setEditFood(f.id);setForm('food')}}>{' '+ui("Edit dish")+' '}</button><p>{f.ingredients.join(', ')||'Ingredients not supplied'}</p><PlantStatement value={f.plant_diet} at={f.plant_diet_recorded_at}/><AllergenStatement value={f.allergens} at={f.allergens_recorded_at}/><DemoImage image={foodImage(f.name)} description={`${f.name} dish`}/></article>)}{!foods.length&&<p>{' '+ui("Add your first dish before creating a batch.")+' '}</p>}</section>}
    {view==='batches'&&<section className="panel detail-panel"><div className="vendor-toolbar"><h2>{' '+ui("Batches ·")+' '}{batches.length}</h2><button className="button secondary" disabled={busy||!!actionRetry||sources.length<2} onClick={()=>void act({kind:'merge',data:{source_ids:sources}})}>{' '+ui("Merge selected (")+' '}{sources.length})</button></div><p className="small muted">{' '+ui("Merging keeps the earliest time and deadline, closes source batches and requires policy reevaluation. Sold-out, withdrawn and discarded batches remain in history.")+' '}</p>{batches.map(b=><BatchCard key={b.id} batch={b} food={foods.find(f=>f.id===b.food_item_id)?.name??'Food'} mode={mode} events={s.events.filter(e=>e.batch_id===b.id)} selected={sources.includes(b.id)} select={checked=>setSources(ids=>checked?[...ids,b.id]:ids.filter(x=>x!==b.id))} busy={busy||!!actionRetry} act={act}/>)}{!batches.length&&<p>{' '+ui("No batches yet. Create one when cooking is finished.")+' '}</p>}</section>}</>
}
function BatchCard({batch:b,food,mode,events,selected,select,busy,act}:{batch:VendorBatch;food:string;mode:AppMode;events:VendorWorkspace['events'];selected:boolean;select:(v:boolean)=>void;busy:boolean;act:(c:Command)=>Promise<void>}) {
  const [quantity,setQuantity]=useState('1');const [correction,setCorrection]=useState('');const open=['active','needs-information'].includes(b.status)
  const action=(name:'consume'|'sold-out'|'withdrawn'|'discarded'|'available'|'correct')=>act({kind:'action',data:{batch_id:b.id,action:name,...(name==='consume'?{quantity:Number(quantity)}:{}),...(name==='correct'&&correction?{prepared_at:new Date(correction).toISOString()}:{})}})
  const time=(v:string)=>new Intl.DateTimeFormat(i18n.language==='ms'?'ms-MY':'en-MY',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(v))
  return <article className="batch-card"><div className="vendor-toolbar"><h3>{food} {' '+ui("· Batch")+' '}{b.batch_number}</h3><span className="status-pill">{ui(b.status)}</span>{open&&<label className="choice-row"><input type="checkbox" checked={selected} onChange={e=>select(e.target.checked)}/>{' '+ui("Merge")+' '}</label>}</div><div className="button-row"><NavLink className="button secondary" to={`/passports/${b.id}`}>{ui('Batch passport')}</NavLink><NavLink className="button secondary" to={`/hawker/handling/${b.id}`}>{ui('Handling & measurements')}</NavLink></div><ImagePlaceholder description={`${food}, prepared batch ${b.batch_number}`}/><p>{' '+ui("Originally prepared:")+' '}<strong>{time(b.prepared_at)}</strong></p><p>{' '+ui("Uploaded / recorded:")+' '}{time(b.uploaded_at)}</p>{b.corrected_prepared_at&&<p>{' '+ui("Earlier correction:")+' '}{time(b.corrected_prepared_at)}</p>}<p>{' '+ui("Remaining:")+' '}{b.remaining_quantity??ui('Unknown')} {' '+ui("· Original:")+' '}{b.original_quantity??ui('Unknown')}</p><p>{b.advisory_deadline?ui('Advisory until {time}',{time:time(b.advisory_deadline)})+(mode==='fixture'?ui(' · Fictional timer'):''):ui("Needs handling policy · no clearance allowed")}</p><div className="button-row">{open&&<><label>{' '+ui("Units sold")+' '}<input type="number" min="1" max={b.remaining_quantity??undefined} value={quantity} onChange={e=>setQuantity(e.target.value)}/></label><button className="button secondary" disabled={busy||b.remaining_quantity===null} onClick={()=>void action('consume')}>{' '+ui("Record sale")+' '}</button><button className="button secondary" disabled={busy||b.remaining_quantity===null} onClick={()=>void action('sold-out')}>{' '+ui("Sold out")+' '}</button><button className="button secondary" disabled={busy} onClick={()=>void action('withdrawn')}>{' '+ui("Withdraw")+' '}</button><button className="button secondary" disabled={busy} onClick={()=>void action('discarded')}>{' '+ui("Discard")+' '}</button></>}{['withdrawn','expired'].includes(b.status)&&<button className="button secondary" disabled={busy} onClick={()=>void action('discarded')}>{' '+ui("Record discard")+' '}</button>}{b.status==='withdrawn'&&<button className="button secondary" disabled={busy} onClick={()=>void action('available')}>{' '+ui("Restore within original window")+' '}</button>}</div><details><summary>{' '+ui("Correction & audit trail")+' '}</summary><label>{' '+ui("Earlier preparation time")+' '}<input type="datetime-local" value={correction} onChange={e=>setCorrection(e.target.value)}/></label><button className="button secondary" disabled={busy||!correction} onClick={()=>void action('correct')}>{' '+ui("Append correction")+' '}</button><p className="small muted">{' '+ui("Original timestamps and photo never change. Corrections can only shorten a window.")+' '}</p>{events.map((e,i)=><p key={i}>{time(e.at)} · {ui(e.kind.replaceAll('-', ' '))}{typeof e.details.remaining==='number'?' · '+ui('{count} remaining',{count:e.details.remaining}):''}{typeof e.details.prepared_at==='string'?` · ${time(e.details.prepared_at)}`:''}{Array.isArray(e.details.source_ids)?' · '+ui('{count} source batches',{count:e.details.source_ids.length}):''}</p>)}</details></article>
}
function ListingForm({mode,kind,data,stallId,foodId,markets,onSaved,onClose}:{mode:AppMode;kind:'stall'|'food'|'batch';data:VendorWorkspace;stallId:string;foodId:string;markets:{id:string;name:string;latitude:number|null;longitude:number|null}[];onSaved:()=>Promise<void>;onClose:()=>void}) {
  const stall=data.stalls.find(s=>s.id===stallId);const editingFood=data.foods.find(f=>f.id===foodId);const storageKey=`pasarmalam:${mode==='fixture'?'demo':'real'}:draft:${kind}:${stallId}:${foodId}`
  const {register,handleSubmit,watch,setValue}=useForm<Fields>({defaultValues:()=>{const draft=sessionStorage.getItem(storageKey);return Promise.resolve(draft?{...defaults,...JSON.parse(draft)} as Fields:{...defaults,...(kind==='food'&&editingFood?{name:editingFood.name,categoryId:editingFood.category_id??categoryId(stall?.category)??'',plantDiet:editingFood.plant_diet??{...unknownPlant},price:(editingFood.price_sen/100).toFixed(2),allergens:editingFood.allergens??{...unknownAllergens,contains:[]},ingredients:editingFood.ingredients.join(', ')}:{}),...(kind==='stall'&&stall?{name:stall.name,market:stall.market_id,category:stall.category,categoryId:stall.category_id??categoryId(stall.category)??'',specialty:stall.specialty,description:stall.description??'',declarations:stall.declarations??{...unknownDeclarations},price:(stall.price_sen/100).toFixed(2),halal:stall.halal,lot:stall.lot,opens:stall.opens,closes:stall.closes,latitude:stall.latitude?.toString()??'',longitude:stall.longitude?.toString()??'',open:stall.open}:{}),market:stall?.market_id??markets[0]?.id??'',food:data.foods.find(f=>f.stall_id===stallId)?.id??'',prepared:localTime(mode==='fixture'?fixtureClock.now():new Date())})}})
  useEffect(()=>{const subscription=watch(values=>sessionStorage.setItem(storageKey,JSON.stringify(values)));return()=>subscription.unsubscribe()},[watch,storageKey])
  const [file,setFile]=useState<File|null>(null);const [progress,setProgress]=useState(0);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [retry,setRetry]=useState<{command:Command;request:string}|null>(()=>{const pending=sessionStorage.getItem(storageKey+':pending');return pending?JSON.parse(pending) as {command:Command;request:string}:null});const [orphan,setOrphan]=useState<string|null>(null)
  function rememberPending(value:{command:Command;request:string}|null){if(value)sessionStorage.setItem(storageKey+':pending',JSON.stringify(value));else sessionStorage.removeItem(storageKey+':pending');setRetry(value)}
  const [entityId]=useState(()=>crypto.randomUUID())
  async function submit(v:Fields) {setBusy(true);setError('');let photo:string|null=null;let attempted=false;try {if(!navigator.onLine)throw new Error('Offline: draft kept, no server save.');if(orphan){await cleanupPhoto(mode,orphan);setOrphan(null)}let command:Command;let request:string
    if(retry){command=retry.command;request=retry.request}
    else {photo=file?await uploadPhoto(mode,stallId,file,setProgress):null
      command=kind==='stall'?{kind:'stall',data:{id:stallId||entityId,market_id:v.market,name:v.name,category_id:(v.categoryId||null) as 'rice'|'skewers'|'kuih'|'drinks'|'fried'|'produce'|null,category:categories.find(c=>c.id===v.categoryId)?.en??v.category,specialty:v.specialty,description:v.description,declarations:v.declarations,price_sen:money(v.price),halal:v.halal,open:v.open,lot:v.lot,opens:v.opens,closes:v.closes,latitude:v.latitude===''?null:Number(v.latitude),longitude:v.longitude===''?null:Number(v.longitude),photo:photo??stall?.photo??null}}:kind==='food'?{kind:'food',data:{id:foodId||entityId,stall_id:stallId,name:v.name,category_id:(v.categoryId||null) as 'rice'|'skewers'|'kuih'|'drinks'|'fried'|'produce'|null,plant_diet:v.plantDiet,price_sen:money(v.price),ingredients:v.ingredients.split(',').map(x=>x.trim()).filter(Boolean),allergens:v.allergens.status==='confirmed'?v.allergens:{...v.allergens,contains:[]},photo:photo??editingFood?.photo??null}}:{kind:'batch',data:{food_item_id:v.food,prepared_at:new Date(v.prepared).toISOString(),quantity:v.quantity===''?null:Number(v.quantity),handling:{storage:v.storage,note:v.note},photo}}
      request=crypto.randomUUID();rememberPending({command,request})
    }
    attempted=true;await save(mode,command,request);sessionStorage.removeItem(storageKey);rememberPending(null);await onSaved()
  }catch(e){setError(errorText(e,'Save failed. Draft retained.'));if(!attempted||e instanceof SaveError&&e.definite){const key=photo??retry?.command.data;const uploaded=typeof key==='string'?key:key&&'photo' in key?key.photo:null;rememberPending(null);if(uploaded){try {await cleanupPhoto(mode,uploaded)}catch {setOrphan(uploaded)}}}}finally{setBusy(false)}}
  // On an ambiguous save failure preserve the uploaded immutable photo and exact retry key.
  // A retry resolves whether the transaction committed; cleanup cannot break a committed batch.
  async function abandon() {if(retry){setError('Resolve the pending save by retrying before closing, so its photo cannot become an orphan.');return}if(orphan){try{await cleanupPhoto(mode,orphan);setOrphan(null)}catch{setError('Cleanup failed. Retry closing while online.');return}}onClose()}
  const chosenMarket=markets.find(m=>m.id===watch('market'))
  return <form className="panel listing-form" onSubmit={handleSubmit(submit)}><h2>{kind==='stall'?ui("Stall details"):kind==='food'?ui("Add a dish"):ui("New batch prepared")}</h2><p className="small muted">{' '+ui("Unsent text is saved as a draft in this tab. Files must be selected again after reload. All preparation times below use this device’s local timezone.")+' '}</p>{retry&&<p>{' '+ui("Pending save: retry sends exactly the same content and request key.")+' '}</p>}{error&&<p role="alert">{ui(error)}</p>}<fieldset disabled={busy||!!retry}>{kind==='stall'&&chosenMarket?.latitude!=null&&chosenMarket.longitude!=null&&<PinPicker latitude={stall?.latitude??chosenMarket.latitude} longitude={stall?.longitude??chosenMarket.longitude} onPick={(lat,lon)=>{if(!busy&&!retry){setValue('latitude',String(lat));setValue('longitude',String(lon))}}}/>}<div className="form-grid">{kind!=='batch'&&<><label>{kind==='stall'?ui("Stall name"):ui("Dish name")}<input required minLength={2} maxLength={100} {...register('name')}/></label><label>{' '+ui("Price (RM)")+' '}<input required inputMode="decimal" {...register('price')}/></label></>}{kind==='stall'&&<><label>{' '+ui("Market")+' '}<select {...register('market')}>{markets.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label>{' '+ui("Category")+' '}<select {...register('categoryId')}><option value="">{ui('Unclassified')}</option>{categories.map(c=><option key={c.id} value={c.id}>{ui(c.en)}</option>)}</select></label><label>{' '+ui("Specialty")+' '}<input required {...register('specialty')}/></label><label>{ui('Stall description')}<textarea maxLength={1000} {...register('description')}/></label>{(Object.keys(labels) as (keyof Declarations)[]).map(key=><label key={key}>{ui(labels[key])}<select {...register(`declarations.${key}`)}><option value="unknown">{ui('Not declared')}</option><option value="yes">{ui('Declared yes')}</option><option value="no">{ui('Declared no')}</option></select></label>)}<p className="small muted">{ui('These voluntary statements are not halal certification. No identity is inferred.')}</p><label>{' '+ui("Lot number")+' '}<input {...register('lot')}/></label><label>{' '+ui("Opens")+' '}<input type="time" {...register('opens')}/></label><label>{' '+ui("Closes")+' '}<input type="time" {...register('closes')}/></label><label>{' '+ui("Pin latitude")+' '}<input type="number" step="any" {...register('latitude')}/></label><label>{' '+ui("Pin longitude")+' '}<input type="number" step="any" {...register('longitude')}/></label><label>{' '+ui("Halal declaration")+' '}<select {...register('halal')}><option value="not-declared">{' '+ui("Not declared")+' '}</option><option value="declared">{' '+ui("Hawker-declared, not certified")+' '}</option><option value="non-halal">{' '+ui("Non-halal")+' '}</option></select></label><label className="choice-row"><input type="checkbox" {...register('open')}/>{' '+ui("Currently open")+' '}</label></>}{kind==='food'&&<><label>{ui('Category')}<select {...register('categoryId')}><option value="">{ui('Unclassified')}</option>{categories.map(c=><option key={c.id} value={c.id}>{ui(c.en)}</option>)}</select></label>{(['vegetarian','vegan'] as const).map(key=><label key={key}>{ui(key==='vegan'?'Vegan declaration':'Vegetarian declaration')}<select {...register(`plantDiet.${key}`)}><option value="unknown">{ui('Not declared')}</option><option value="yes">{ui('Declared yes')}</option><option value="no">{ui('Declared no')}</option></select></label>)}<p className="small muted">{ui('Review ingredients before declaring. Plant diet is separate from halal and allergens; speech never declares it.')}</p><label>{' '+ui("Ingredients, separated by commas")+' '}<textarea {...register('ingredients',{onChange:()=>{setValue('allergens.status','unknown');setValue('plantDiet',{...unknownPlant})}})}/></label><fieldset className="allergen-editor"><legend>{ui('Allergen information')}</legend><p className="small muted">{ui('Confirm after reviewing ingredients. Editing ingredients clears confirmation; speech never infers allergens.')}</p>{allergenCodes.map(code=><label className="choice-row" key={code}><input type="checkbox" value={code} {...register('allergens.contains')}/>{ui(allergenLabels[code])}</label>)}<label>{ui('Cross-contact')}<select {...register('allergens.cross_contact')}><option value="unknown">{ui('Unknown')}</option><option value="possible">{ui('Possible')}</option></select></label><label className="choice-row"><input type="checkbox" checked={watch('allergens.status')==='confirmed'} onChange={e=>setValue('allergens.status',e.target.checked?'confirmed':'unknown')}/>{ui('I reviewed this allergen statement')}</label><p className="small muted">{ui('No allergens listed — this is not an allergen-free claim')}</p></fieldset></>}{kind==='batch'&&<><label>{' '+ui("Food")+' '}<select {...register('food')}>{data.foods.filter(f=>f.stall_id===stallId).map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></label><label>{' '+ui("Prepared at")+' '}<input required type="datetime-local" {...register('prepared')}/></label><label>{' '+ui("Quantity (optional)")+' '}<input type="number" min="1" max="100000" {...register('quantity')}/></label><label>{' '+ui("Handling")+' '}<select {...register('storage')}><option value="unknown">{' '+ui("Unknown — needs information")+' '}</option><option value="ambient">{' '+ui("Ambient")+' '}</option><option value="chilled">{' '+ui("Chilled")+' '}</option><option value="hot-held">{' '+ui("Hot held")+' '}</option></select></label><label>{' '+ui("Handling notes")+' '}<textarea maxLength={500} {...register('note')}/></label></>}<label><Camera size={18}/> {kind==='batch'?ui("Batch photo"):ui("Listing photo")}<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" disabled={kind==='stall'&&!stallId} onChange={e=>setFile(e.target.files?.[0]??null)}/>{kind==='stall'&&!stallId&&<span className="small">{' '+ui("Save the stall before adding its photo.")+' '}</span>}</label></div></fieldset>{progress>0&&<p role="status">{' '+ui("Photo processing / transfer")+' '}<progress max="100" value={progress}/> {progress}%</p>}<div className="button-row"><button className="button primary" type="submit" disabled={busy||kind==='batch'&&!data.foods.some(f=>f.stall_id===stallId)}>{busy?ui("Saving…"):retry?ui("Retry pending save"):ui('Save '+kind)}</button><button className="button secondary" type="button" disabled={busy} onClick={()=>void abandon()}>{' '+ui("Close")+' '}</button></div></form>
}
